{"command": "create", "path": "/app/workspace/run_ocr.py", "file_text": "import os
import re
from pathlib import Path
from datetime import datetime

import pytesseract
from PIL import Image, ImageOps, ImageFilter
from openpyxl import Workbook

IMG_DIR = Path("/app/workspace/dataset/img")
OUT = Path("/app/workspace/stat_ocr.xlsx")

PRIORITY = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    ["TOTAL DUE", "AMOUNT DUE", "BALANCE DUE", "NETT TOTAL", "NET TOTAL", "TOTAL", "AMOUNT"],
]
EXCLUDE = ["SUBTOTAL", "SUB TOTAL", "TAX", "GST", "SST", "DISCOUNT", "CHANGE", "CASH TENDERED"]
NUM = re.compile(r"(?<![\d.])\d{1,3}(?:,\d{3})*\.\d{2}(?!\d)")


def _clean(line: str) -> str:
    # Collapse spaces inside numbers like '92 80' -> '92.80'
    return re.sub(r"(\d)\s+(\d{2})\b", r"\1.\2", line)


def extract_total(text: str):
    lines = [_clean(l.strip()) for l in text.splitlines()]
    for group in PRIORITY:
        for i, line in enumerate(lines):
            U = line.upper()
            if any(x in U for x in EXCLUDE):
                continue
            if not any(k in U for k in group):
                continue
            nums = [m.replace(",", "") for m in NUM.findall(line)]
            if nums:
                return "{:.2f}".format(float(nums[-1]))
            for j in range(i + 1, min(i + 3, len(lines))):
                if not lines[j]:
                    continue
                nxt = [m.replace(",", "") for m in NUM.findall(lines[j])]
                if nxt:
                    return "{:.2f}".format(float(nxt[-1]))
                break
    return None


_DATE_TRIES = [
    (re.compile(r"\b(\d{4}-\d{1,2}-\d{1,2})\b"), ["%Y-%m-%d"]),
    (re.compile(r"\b(\d{1,2}[/.\-]\d{1,2}[/.\-]\d{4})\b"), ["%d/%m/%Y", "%d-%m-%Y", "%d.%m.%Y"]),
    (re.compile(r"\b(\d{1,2}[/.\-]\d{1,2}[/.\-]\d{2})\b"), ["%d/%m/%y", "%d-%m-%y", "%d.%m.%y"]),
    (re.compile(r"\b(\d{1,2}\s+[A-Za-z]{3,9}\s+\d{4})\b"), ["%d %b %Y", "%d %B %Y"]),
]


def extract_date(text: str):
    for rx, fmts in _DATE_TRIES:
        for m in rx.finditer(text):
            s = m.group(1)
            for f in fmts:
                try:
                    return datetime.strptime(s, f).strftime("%Y-%m-%d")
                except ValueError:
                    pass
    return None


def ocr_passes(path: Path):
    img = Image.open(path)
    gray = ImageOps.grayscale(img)
    auto = ImageOps.autocontrast(gray)

    w, h = auto.size
    up2 = auto.resize((w * 2, h * 2), Image.LANCZOS)
    up3 = auto.resize((w * 3, h * 3), Image.LANCZOS)
    sharp = auto.filter(ImageFilter.SHARPEN)

    passes = [
        (img, ""),
        (auto, "--psm 6"),
        (up2, "--psm 6"),
        (up3, "--psm 4"),
        (sharp, "--psm 11"),
    ]
    texts = []
    for im, cfg in passes:
        try:
            texts.append(pytesseract.image_to_string(im, config=cfg))
        except Exception:
            texts.append("")
    return texts


def pick_total(texts):
    cands = [extract_total(t) for t in texts]
    non_null = [c for c in cands if c is not None]
    if not non_null:
        return None
    # Majority agreement
    counts = {}
    for c in non_null:
        counts[c] = counts.get(c, 0) + 1
    best = max(counts.items(), key=lambda kv: kv[1])
    if best[1] >= 2:
        return best[0]
    return non_null[0]


def pick_date(texts):
    for t in texts:
        d = extract_date(t)
        if d:
            return d
    return None


def main():
    files = sorted(p for p in IMG_DIR.iterdir() if p.suffix.lower() in {".jpg", ".jpeg", ".png"})
    rows = []
    for p in files:
        texts = ocr_passes(p)
        total = pick_total(texts)
        date = pick_date(texts)
        print(f"{p.name}\t{date}\t{total}")
        rows.append((p.name, date, total))

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    rows.sort(key=lambda r: r[0])
    for fn, d, t in rows:
        ws.append([fn, d if d else None, t if t else None])
    # Force total_amount to text format so '92.80' retains trailing zero.
    for cell in ws["C"][1:]:
        cell.number_format = "@"
    assert wb.sheetnames == ["results"], wb.sheetnames
    wb.save(OUT)
    print("Saved", OUT)


if __name__ == "__main__":
    main()
"}

