{"command": "str_replace", "new_str": "# Priority tiers, searched in order. Within each tier same-line matches win
# over two-line fallbacks; among same-line matches we take the last (totals
# generally come after sub-totals).
PRIORITY = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    ["TOTAL DUE", "AMOUNT DUE", "BALANCE DUE", "NETT TOTAL", "NET TOTAL"],
    ["TOTAL"],
    ["AMOUNT"],
]
HARD_EXCLUDE = ["SUBTOTAL", "SUB TOTAL", "DISCOUNT", "CHANGE", "CASH TENDERED"]
TAX_WORDS = ["TAX", "GST", "SST"]
TAX_OK_WORDS = ["INCL"]  # covers INCLUDING, INCLUSIVE, INCL.
SUMMARY_HEADERS = ["GST SUMMARY", "TAX SUMMARY"]
NUM = re.compile(r"(?<![\d.])\d{1,3}(?:,\d{3})*\.\d{2}(?!\d)")
