# part of a decimal number) so we don't merge across a real "0.59 10.40" pair.
_SPACE_FIX = re.compile(r"(?<![\d.])(\d{1,3})\s+(\d{2})(?!\d)")


def _clean(line: str) -> str:
    return _SPACE_FIX.sub(r"\1.\2", line)


def _is_excluded(upper_line: str) -> bool:
    if any(x in upper_line for x in HARD_EXCLUDE):
        return True
    if any(x in upper_line for x in TAX_WORDS) and not any(w in upper_line for w in TAX_OK_WORDS):
        return True
    return False


